package com.formation.loan.mapper; import com.formation.loan.dto.LoanResponse; import com.formation.loan.model.Loan; public final class LoanMapper {private LoanMapper(){} public static LoanResponse toResponse(Loan l){return new LoanResponse(l.getId(),l.getMemberName(),l.getBookId(),l.getBookTitle(),l.getBookAuthor(),l.getBookIsbn(),l.getLoanDate(),l.getDueDate(),l.getReturnDate(),l.getStatus());}}
